/**
 * Slack Node - Version 2.7
 * Discriminator: resource=channel, operation=join
 */


interface Credentials {
  slackApi: CredentialReference;
  slackOAuth2Api: CredentialReference;
}

/** Joins an existing conversation */
export type SlackV27ChannelJoinParams = {
  resource: 'channel';
  operation: 'join';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The Slack channel to join
 * @searchListMethod getChannels
 * @default {"mode":"list","value":""}
 */
    channelId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
};

export type SlackV27ChannelJoinNode = {
  type: 'n8n-nodes-base.slack';
  version: 2.7;
  config: NodeConfig<SlackV27ChannelJoinParams> & { credentials?: Credentials };
};